// Test-only binary plist encoder for the standard types used by Swift Codable.
function plist(value) {
  const objects = [];
  const lengthPrefix = (type, length) => {
    if (length < 15) return Buffer.from([(type << 4) | length]);
    const prefix = Buffer.alloc(6); prefix[0] = (type << 4) | 15;
    prefix[1] = 0x12; prefix.writeUInt32BE(length, 2); return prefix;
  };
  const refs = indices => {
    const result = Buffer.alloc(indices.length * 2);
    indices.forEach((index, i) => result.writeUInt16BE(index, i * 2)); return result;
  };
  function add(item) {
    const index = objects.length; objects.push(null);
    if (item === null) objects[index] = Buffer.from([0]);
    else if (typeof item === 'boolean') objects[index] = Buffer.from([item ? 9 : 8]);
    else if (Buffer.isBuffer(item)) objects[index] = Buffer.concat([lengthPrefix(4, item.length), item]);
    else if (item instanceof Date) {
      const data = Buffer.alloc(9); data[0] = 0x33;
      data.writeDoubleBE((item.getTime() - Date.UTC(2001, 0, 1)) / 1000, 1); objects[index] = data;
    } else if (typeof item === 'string') {
      if (!/^[\x20-\x7e]*$/.test(item)) throw new Error('fixture string must be printable ASCII');
      objects[index] = Buffer.concat([lengthPrefix(5, item.length), Buffer.from(item, 'ascii')]);
    } else if (typeof item === 'number') {
      const data = Buffer.alloc(9); data[0] = 0x13; data.writeBigUInt64BE(BigInt(item), 1); objects[index] = data;
    } else if (Array.isArray(item)) objects[index] = Buffer.concat([lengthPrefix(10, item.length), refs(item.map(add))]);
    else {
      const entries = Object.entries(item);
      const keys = entries.map(([key]) => add(key)); const values = entries.map(([, v]) => add(v));
      objects[index] = Buffer.concat([lengthPrefix(13, entries.length), refs([...keys, ...values])]);
    }
    return index;
  }
  add(value);
  const offsets = []; let offset = 8;
  for (const object of objects) { offsets.push(offset); offset += object.length; }
  const table = Buffer.alloc(objects.length * 4);
  offsets.forEach((item, i) => table.writeUInt32BE(item, i * 4));
  const trailer = Buffer.alloc(32); trailer[6] = 4; trailer[7] = 2;
  trailer.writeBigUInt64BE(BigInt(objects.length), 8); trailer.writeBigUInt64BE(0n, 16);
  trailer.writeBigUInt64BE(BigInt(offset), 24);
  return Buffer.concat([Buffer.from('bplist00'), ...objects, table, trailer]);
}

function packageBytes(bundleID) {
  const packageID = crypto.randomUUID().toUpperCase(), ruleID = crypto.randomUUID().toUpperCase();
  const replacement = Buffer.from('public custom-target replacement bytes');
  const payload = { project: { id: packageID, name: 'Public custom target fixture', author: '', isPrivate: false,
    createdAt: new Date('2025-01-01T00:00:00Z'), updatedAt: new Date('2025-01-01T00:00:00Z'),
    bundleIdentifiers: [bundleID], directories: [],
    rules: [{ id: ruleID, bundleID, relativePath: 'Documents/custom-fixture.bin',
      replacementFilename: 'custom-fixture.bin', replacementData: replacement }] },
    replacementDigests: { [ruleID]: crypto.createHash('sha256').update(replacement).digest() } };
  const key = crypto.randomBytes(32), nonce = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, nonce);
  cipher.setAAD(Buffer.from(`3105PATCH/v3/payload/${packageID}`));
  const ciphertext = Buffer.concat([cipher.update(plist(payload)), cipher.final()]);
  return Buffer.concat([Buffer.from('3105PATCH\0'), plist({schemaVersion:3,packageID,isPasswordProtected:false,
    publicContentKey:key,keyFingerprint:crypto.createHash('sha256').update(key).digest(),
    encryptedPayload:Buffer.concat([nonce,ciphertext,cipher.getAuthTag()])})]);
}

const {privateKey,publicKey} = crypto.generateKeyPairSync('rsa',{modulusLength:2048});
