  const created = artifacts.createArtifact({plaintext:plain,masterKey,masterKeyId,signer,
    metadata:{artifactId:id,releaseId:'catalog-custom-'+sourceId,releaseVersion:1,variant,kind:'package',fileName:'protected.3105'}});
  const signedGrant = artifacts.issueDownloadGrant({signedManifest:created.signedManifest,serverKeyEnvelope:created.serverKeyEnvelope,
    masterKey,masterKeyId,recipientPublicKeyX963:recipient.getPublicKey(undefined,'uncompressed').toString('base64'),
    recipientId:context.recipientId,sessionId:context.sessionId,grantId:crypto.randomUUID(),requestNonce:context.requestNonce,
    issuedAt:context.now,expiresAt:context.now+60,signer});
  fs.writeFileSync(path.join(folder,sourceId+'.3105'),plain);
